    </template>

    <pm-form-dialog v-model:dialog-visible="scheduleVisible" :title="editingSchedule?'调整排班':'新增排班'" width="560px" @submit="saveSchedule"><template #form><el-form :model="scheduleEditor" label-position="top" style="padding:20px"><div class="dialog-form-grid"><el-form-item label="客服姓名" prop="staff" required><pm-input size="default" v-model="scheduleEditor.staff" /></el-form-item><el-form-item label="技能组" prop="skill"><pm-input size="default" v-model="scheduleEditor.skill" /></el-form-item><el-form-item label="所属班组" prop="group"><pm-select size="default" v-model="scheduleEditor.group" :options="groupOptions" /></el-form-item><el-form-item label="班次" prop="shift"><pm-select size="default" v-model="scheduleEditor.shift" :options="shiftOptions" /></el-form-item></div></el-form></template></pm-form-dialog>
    <pm-form-dialog v-model:dialog-visible="issueVisible" title="处理订单异常" width="580px" @submit="saveIssue"><template #form><div style="padding:20px"><div class="issue-dialog-summary"><span>订单编号</span><strong>{{issueEditor.orderNo}}</strong></div><el-form :model="issueEditor" label-position="top"><el-form-item label="处理方式" prop="method"><pm-select size="default" v-model="issueEditor.method" :options="methodOptions" style="width:100%" /></el-form-item><el-form-item label="处理说明" prop="note" required><pm-textarea size="default" v-model="issueEditor.note" :rows="4" placeholder="填写判断依据、处理动作和用户沟通结果" /></el-form-item></el-form></div></template></pm-form-dialog>
