<script setup>
import { computed, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Plus } from '@element-plus/icons-vue'


const page = 'schedule'
const options=values=>values.map(value=>({label:value,value}))
const reportDate=ref('2026-11-11')
const ticketTrendOption={chartView:{grid:{left:38,right:18,top:22,bottom:28},tooltip:{trigger:'axis'},legend:{data:['受理量','完成量']},xAxis:{type:'category',data:['周四','周五','周六','周日','周一','周二','周三']},yAxis:{type:'value'},series:[{name:'受理量',type:'bar',data:[62,78,71,88,84,96,89],itemStyle:{color:'#c2542a'}},{name:'完成量',type:'line',smooth:true,data:[58,74,69,81,80,90,86],lineStyle:{color:'#8f684f',width:3},itemStyle:{color:'#8f684f'}}]}}
const metrics=[{label:'今日订单',value:'12,684',note:'较昨日 +8.2%',tone:'up'},{label:'已处理工单',value:'1,028',note:'完成率 94.6%',tone:'up'},{label:'客服在线率',value:'97.3%',note:'高于目标 2.3%',tone:'up'},{label:'异常待办',value:'18',note:'高优先级 3 项',tone:'warn'}]
const todos=[{name:'待复核订单异常',count:7,owner:'周宁',deadline:'11:30 前',level:'danger'},{name:'公告草稿待发布',count:4,owner:'王可',deadline:'今日',level:'warning'},{name:'排班冲突待调整',count:3,owner:'陈雨',deadline:'12:00 前',level:'warning'},{name:'权限申请待审批',count:8,owner:'林晓',deadline:'今日',level:'normal'}]
