const groupOptions=options(['华东一组','华东二组','全国夜班组','售后专项组']),shiftOptions=options(['早班 08:00-16:00','中班 14:00-22:00','夜班 22:00-08:00'])
const shiftSummary=[{name:'早班',time:'08:00 - 16:00',current:23,target:24,rate:96,note:'缺口 1 人'},{name:'中班',time:'14:00 - 22:00',current:18,target:20,rate:90,note:'缺口 2 人'},{name:'夜班',time:'22:00 - 08:00',current:12,target:12,rate:100,note:'覆盖完整'},{name:'专项支援',time:'大促机动',current:8,target:10,rate:80,note:'缺口 2 人'}]
