  {id:2,staff:'周安',skill:'订单售后',group:'华东二组',shift:'中班 14:00-22:00',date:'11-12',load:'82%',status:'待确认'},
  {id:3,staff:'林川',skill:'支付问题 / 英语',group:'全国夜班组',shift:'夜班 22:00-08:00',date:'11-12',load:'64%',status:'已确认'},
