])
const scheduleColumns=[{prop:'staff',label:'客服信息',minWidth:170,scope:'staff'},{prop:'group',label:'所属班组',width:120},{prop:'shift',label:'班次',minWidth:170},{prop:'date',label:'值班日期',width:95},{prop:'load',label:'预计负载',width:100},{prop:'status',label:'状态',width:100,scope:'status'},{prop:'action',label:'操作',width:120,scope:'action'}]
const filteredSchedules=computed(()=>schedules.value.filter(row=>(!scheduleFilter.value.name||row.staff.includes(scheduleFilter.value.name))&&(!scheduleFilter.value.group||row.group===scheduleFilter.value.group)&&(!scheduleFilter.value.shift||row.shift===scheduleFilter.value.shift)))
const pagedSchedules=computed(()=>filteredSchedules.value.slice((scheduleCurrentPage.value-1)*schedulePageSize,scheduleCurrentPage.value*schedulePageSize))
const onlineCount=computed(()=>schedules.value.filter(row=>row.status==='已确认').length),pendingCount=computed(()=>schedules.value.filter(row=>row.status==='待确认').length)
const scheduleVisible=ref(false),editingSchedule=ref(null),scheduleEditor=reactive({staff:'',skill:'订单售后',group:'华东一组',shift:'早班 08:00-16:00'})
const openSchedule=row=>{editingSchedule.value=row?.id||null;Object.assign(scheduleEditor,row||{staff:'',skill:'订单售后',group:'华东一组',shift:'早班 08:00-16:00'});scheduleVisible.value=true}
const saveSchedule=()=>{if(!scheduleEditor.staff)return ElMessage.warning('请输入客服姓名');if(editingSchedule.value)Object.assign(schedules.value.find(row=>row.id===editingSchedule.value),scheduleEditor);else schedules.value.push({...scheduleEditor,id:Date.now(),date:'11-15',load:'待评估',status:'待确认'});scheduleVisible.value=false;ElMessage.success('排班已保存')}
