  {orderNo:'SO202611110089',customer:'上海星禾商贸',amount:'¥18,620',reason:'支付成功未入账',priority:'紧急',sla:'剩余 12 分钟',owner:'周宁',status:'待处理'},
  {orderNo:'SO202611110072',customer:'杭州远山科技',amount:'¥6,980',reason:'优惠金额计算异常',priority:'高',sla:'剩余 46 分钟',owner:'陈雨',status:'待复核'},
  {orderNo:'SO202611100316',customer:'苏州新原实业',amount:'¥32,450',reason:'重复扣款',priority:'紧急',sla:'已超时 8 分钟',owner:'林晓',status:'处置中'},
  {orderNo:'SO202611100288',customer:'宁波森途贸易',amount:'¥4,260',reason:'退款到账延迟',priority:'普通',sla:'剩余 2 小时',owner:'王可',status:'待处理'},
  {orderNo:'SO202611100241',customer:'无锡嘉品家居',amount:'¥12,800',reason:'发票金额不一致',priority:'高',sla:'剩余 35 分钟',owner:'赵洋',status:'处置中'},
  {orderNo:'SO202611090826',customer:'合肥青禾食品',amount:'¥8,660',reason:'优惠券错误核销',priority:'普通',sla:'剩余 3 小时',owner:'周宁',status:'待复核'},
])
const issueColumns=[{prop:'orderNo',label:'订单与客户',minWidth:190,scope:'order'},{prop:'amount',label:'订单金额',width:105},{prop:'reason',label:'异常原因',minWidth:160},{prop:'priority',label:'优先级',width:85,scope:'priority'},{prop:'sla',label:'SLA / 负责人',width:125,scope:'sla'},{prop:'status',label:'状态',width:95,scope:'status'},{prop:'action',label:'操作',width:120,scope:'action'}]
const filteredIssues=computed(()=>issues.value.filter(row=>issueLevel.value==='全部'||row.priority===issueLevel.value))
const pagedIssues=computed(()=>filteredIssues.value.slice((issueCurrentPage.value-1)*issuePageSize,issueCurrentPage.value*issuePageSize))
const priorityClass=value=>value==='紧急'?'danger':value==='高'?'warning':'normal'
const issueVisible=ref(false),issueEditor=reactive({orderNo:'',method:'原路退款',note:''}),methodOptions=options(['原路退款','人工补账','重新计算优惠','转交技术排查'])
const openIssue=row=>{Object.assign(issueEditor,{orderNo:row.orderNo,method:'原路退款',note:''});issueVisible.value=true}
const saveIssue=()=>{if(!issueEditor.note)return ElMessage.warning('请填写处理说明');const row=issues.value.find(item=>item.orderNo===issueEditor.orderNo);row.status='待复核';issueVisible.value=false;ElMessage.success('处理结果已提交复核')}
</script>

